@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--gold:#e7bc6c;--gold-bright:#ffda8b;--ink:#101522;--panel:rgba(16,21,34,.86);--muted:#a9b5c5;--line:rgba(233,224,198,.16);--cyan:#83ded3}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101522;color:#fff;font-family:Manrope,system-ui,sans-serif;touch-action:none;user-select:none;-webkit-user-select:none}.game-shell{position:relative;width:100%;height:100%;overflow:hidden;background:#18282c;isolation:isolate}#world{position:absolute;inset:0;width:100%;height:100%;display:block;image-rendering:pixelated}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,13,25,.64),transparent 25%,transparent 65%,rgba(8,13,25,.72)),radial-gradient(ellipse at 50% 45%,transparent 35%,rgba(8,13,25,.22) 100%)}.topbar{position:absolute;z-index:2;top:0;left:0;right:0;height:79px;padding:0 31px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(11,17,29,.92),rgba(11,17,29,.52));border-bottom:1px solid rgba(255,255,255,.07)}.brand{display:flex;align-items:center;gap:12px;color:#f5ebd7;text-decoration:none;font-size:16px;font-weight:800;letter-spacing:2px;line-height:1}.brand i{font-size:10px;font-weight:500;color:#d8bf8c;font-style:normal}.brand small{display:block;color:#a6a99f;font-family:'DM Mono',monospace;font-size:8px;letter-spacing:2.2px;margin-top:7px}.brand-mark{display:grid;place-items:center;width:39px;height:39px;border:1px solid rgba(234,197,122,.64);border-radius:11px;color:#f1ce84;font-size:22px;background:linear-gradient(145deg,rgba(226,182,98,.2),rgba(10,23,29,.8));box-shadow:0 0 23px #dca85524}.world-tag,.top-actions,.map-label,.map-coords,.world-hint{display:flex;align-items:center}.world-tag{gap:9px;color:#c9d1d1;font:10px 'DM Mono',monospace;letter-spacing:1.35px}.world-tag b{color:#d8b26b}.live-dot{height:6px;width:6px;border-radius:50%;background:#76d5ae;box-shadow:0 0 8px #6fe3b1}.top-actions{gap:8px}.icon-btn{width:34px;hei