e;right:14px;top:11px;color:#b7c0c1;border:0;background:none;font-size:23px;cursor:pointer}.modal-kicker{color:#e2bd77;font:9px 'DM Mono',monospace;letter-spacing:2px}.modal h1{margin:10px 0 8px;font-size:25px;letter-spacing:-.7px}.modal>p:not(.compat){margin:0;color:#aeb8bf;font-size:11px;line-height:1.7}.control-list{display:grid;grid-template-columns:1fr 1fr;gap:13px 10px;margin:21px 0;padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.control-list>div{display:flex;align-items:center;gap:9px}.control-list>div>b{display:grid;place-items:center;width:28px;height:28px;border-radius:7px;color:#e5c27b;background:#e5c27b14;border:1px solid #e5c27b35}.control-list strong,.control-list small{display:block}.control-list strong{font-size:10px}.control-list small{margin-top:3px;color:#9daab1;font-size:8px}.language-label{display:block;color:#acb3b3;font:8px 'DM Mono',monospace;letter-spacing:1.3px}.modal select{width:100%;margin-top:7px;padding:9px 10px;border:1px solid #ffffff25;border-radius:7px;color:#eee;background:#1a2230;font:11px Manrope}.primary-btn{width:100%;margin-top:14px;padding:12px;border:1px solid #f1d495;border-radius:7px;background:linear-gradient(100deg,#d7ad67,#edcf8e);color:#221c18;font:800 10px 'DM Mono',monospace;letter-spacing:1.1px;cursor:pointer}.primary-btn span{float:right;font-size:15px;line-height:10px}.modal .compat{text-align:center;margin:14px 0 0;color:#7f8a91;font:7px 'DM Mono',monospace;letter-spacing:1px}.level-flash{position:absolute;left:50%;top:37%;transform:translate(-50%,-15px);display:flex;flex-direction:column;align-items:center;gap:5px;color:#ffe1a0;opacity:0;transition:.4s;pointer-events:none;text-shadow:0 3px 16px #211605}.level-flash.show{opacity:1;transform:translate(-50%,0)}.level-flash span{font-size:31px}.level-flash b{font-size:18px;letter-spacing:3px}.level-flash small{font:9px 'DM Mono',monospace;letter-spacing:2px}.gamepad-status{position:absolute;top:88px;left:50%;transform:translateX