--- game.js
+++ game.js
@@ -74,9 +74,10 @@
     particles.forEach(p=>{const [sx,sy]=screen(p.x,p.y,cameraX,cameraY);ctx.globalAlpha=Math.max(0,p.life/p.max);ctx.fillStyle=p.color;ctx.fillRect(sx,sy,p.size,p.size)});ctx.globalAlpha=1;
     const grad=ctx.createRadialGradient(W*.5,H*.48,60,W*.5,H*.48,Math.max(W,H)*.65);grad.addColorStop(0,'rgba(250,220,165,0)');grad.addColorStop(1,'rgba(8,15,23,.18)');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);ctx.restore();drawMinimap()}
   function update(dt){now+=dt;if(paused)return;const v=moveVec();if(Math.hypot(v.x,v.y)>.05){player.dir=Math.atan2(v.y,v.x);if(player.dodge<=0){player.vx=v.x*210;player.vy=v.y*210}}else if(player.dodge<=0){player.vx*=Math.pow(.001,dt);player.vy*=Math.pow(.001,dt)}
     player.x=Math.max(80,Math.min(mapSize-80,player.x+player.vx*dt));player.y=Math.max(80,Math.min(mapSize-80,player.y+player.vy*dt));player.anim+=dt;player.attack=Math.max(0,player.attack-dt);player.dodge=Math.max(0,player.dodge-dt);player.skill=Math.max(0,player.skill-dt);player.invuln=Math.max(0,player.invuln-dt);cameraX+=(player.x-cameraX)*Math.min(1,dt*5);cameraY+=(player.y-cameraY)*Math.min(1,dt*5);
