el{position:absolute;left:2px;top:-18px;color:#e6d5aa;font:8px 'DM Mono',monospace;letter-spacing:1.4px}.hotbar-label small{margin-left:7px;color:#909ca4}.hotbar{display:flex;padding:5px;gap:4px;border:1px solid #eee1c439;border-radius:11px;background:#111723df;box-shadow:0 8px 32px #080a0f8a;backdrop-filter:blur(8px)}.slot{position:relative;width:58px;height:62px;padding:4px 2px 3px;border:1px solid transparent;border-radius:7px;background:#ffffff07;color:#fff;cursor:pointer}.slot.active{background:linear-gradient(145deg,#d9ae6233,#f1d39010);border-color:#e4bf79;box-shadow:inset 0 0 15px #e4bf7918,0 0 12px #ddb86b20}.slot .item{display:block;height:34px;font-size:23px;line-height:31px;text-shadow:0 0 10px currentColor}.slot .gem{color:#75e3d3}.slot .potion{color:#d895df}.slot .block{color:#b4c9a0}.slot .star{color:#e7bc6c}.slot small{display:block;color:#b8c0c3;font:6px 'DM Mono',monospace;letter-spacing:.2px;white-space:nowrap}.slot small b{color:#fff}.slot kbd{position:absolute;top:3px;left:5px;color:#a9b2b4;font:7px 'DM Mono',monospace}.world-hint{height:41px;gap:7px;margin-left:4px;color:#c7c6b6;font:8px 'DM Mono',monospace;letter-spacing:.5px;white-space:nowrap}.world-hint span{color:#efd084;font-size:16px}.world-hint i{font-style:normal;color:#e8c676}.touch-controls{display:none}.desktop-hint{position:absolute;right:25px;bottom:29px;color:#b4bfbe;font:8px 'DM Mono',monospace;letter-spacing:.7px}.desktop-hint kbd{padding:4px 6px;border:1px solid #ffffff3b;border-radius:4px;background:#121924ca;color:#eee0bd;margin-left:7px}.modal-backdrop{position:absolute;inset:0;z-index:8;display:grid;place-items:center;background:rgba(7,11,20,.62);backdrop-filter:blur(5px);transition:opacity .2s}.modal-backdrop.hidden{display:none}.modal{position:relative;width:min(440px,calc(100vw - 32px));padding:30px 34px 25px;border:1px solid #d9b66f55;border-radius:16px;background:linear-gradient(145deg,#202536f5,#141c27f5);box-shadow:0 25px 100px #05070bbd}.modal-close{position:absolu