const combatEnemies=()=>worldMode==='dungeon'?dungeon.guards:enemies;
function defeatEnemy(e){e.alive=false;essence++;player.xp+=15;if(player.xp>=100){player.xp-=100;player.level++;$('levelFlash').classList.add('show');setTimeout(()=>$('levelFlash').classList.remove('show'),2100)}if(worldMode==='dungeon'&&dungeon.guards.every(g=>!g.alive)){dungeonCleared=true;if(!dungeonRewarded){dungeonRewarded=true;gemCount+=3;gemBoxes++;essence+=3;toast(dw('reward'))}else toast(dw('clear'))}updateHud()}
function attack(){if(player.attack>0||paused)return;player.attack=.25;let hits=0;combatEnemies().forEach(e=>{if(!e.alive)return;const dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),ang=Math.atan2(dy,dx);if(d<100&&Math.cos(ang-player.dir)>.1){e.hp--;e.hit=.25;hits++;burst(e.x,e.y,'#f8bc74',6);if(e.hp<=0)defeatEnemy(e)}});toast(t('attack'));camShake=hits?5:1}
function skill(){if(player.skill>0||paused)return;player.skill=5;player.attack=.4;combatEnemies().forEach(e=>{if(e.alive&&Math.hypot(e.x-player.x,e.y-player.y)<190){e.hp-=3;e.hit=.4;burst(e.x,e.y,'#b58dff',9);if(e.hp<=0)defeatEnemy(e)}});burst(player.x,player.y,classes[classIndex].color,26);camShake=8;toast(`${t('skill')} · ${classes[classIndex].skill}`);updateHud()}

