const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const target = targets.find(item => item.url === 'http://127.0.0.1:8765/');
if (!target) {
  console.log('Browser game tab is not available.');
  process.exit(0);
}
const socket = new WebSocket(target.webSocketDebuggerUrl);
let id = 0;
const pending = new Map();
socket.onmessage = event => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
};
await new Promise(resolve => socket.onopen = resolve);
const send = (method, params = {}) => new Promise(resolve => {
  const requestId = ++id;
  pending.set(requestId, resolve);
  socket.send(JSON.stringify({ id: requestId, method, params }));
});
const result = await send('Runtime.evaluate', {
  expression: 'Array.from(navigator.getGamepads?.() || []).filter(Boolean).map(g => ({id:g.id, connected:g.connected, buttons:g.buttons.length, axes:g.axes.length}))',
  returnByValue: true
});
console.log('Connected gamepads:', result.result?.result?.value ?? []);
socket.close();
