let drawDistance=900,fxEnabled=true,zoneRestriction='public',localClub=null,clubInvites=[];
try{const saved=JSON.parse(localStorage.getItem('shardsOptions')||'{}');drawDistance=Math.max(300,Math.min(2000,Number(saved.drawDistance)||900));fxEnabled=saved.fxEnabled!==false;localClub=saved.localClub||null;clubInvites=Array.isArray(saved.clubInvites)?saved.clubInvites:[]}catch(_){/* Storage can be unavailable in private browsing. */}
const saveOptions=()=>{try{localStorage.setItem('shardsOptions',JSON.stringify({drawDistance,fxEnabled,localClub,clubInvites}))}catch(_){/* Keep the current session usable without storage. */}};
function refreshClub(){const status=$('clubStatus');if(status)status.textContent=localClub?`Clube local: ${localClub.name}${localClub.primary?' · principal':''} · ${clubInvites.length} convite(s) simulado(s).`:'Sem clube criado neste dispositivo.'}
function showModal(section='help'){paused=true;$('modalBackdrop').classList.remove('hidden');['help','settings','club'].forEach(name=>$(`${name}Content`).classList.toggle('hidden',name!==section));$('modalTitle').textContent=section==='settings'?'Configurações':section==='club'?'Clubes locais':t('title');$('modalText').textContent=section==='help'?t('intro'):section==='club'?'Gestão de clube em modo local de demonstração.':'Ajuste a apresentação para este dispositivo.';refreshClub()}
function closeModal(){paused=false;$('modalBackdrop').classList.add('hidden')}
function openCommand(){closeModal();$('commandForm').classList.remove('hidden');$('commandInput').value='';$('commandInput').focus()}
function runCommand(raw){const parts=raw.trim().replace(/^\\//,'').split(/\\s+/),cmd=(parts.shift()||'').toLowerCase(),arg=parts.shift();if(!cmd)return;
  if(cmd==='club'){if(!arg){$('commandForm').classList.add('hidden');showModal('club');return}if(arg.toLowerCase()==='invite'){const name=parts.join(' ').trim();if(!name){toast('Uso: /club invite [NomeDoJogador]');return}if(!localClub){toast('Crie primeiro um clube local em /club.');return}clubInvites.push(name);saveOptions();refreshClub();toast(`Convite local simulado para ${name}.`);return}if(arg.toLowerCase()==='makeprimary'){if(!localClub){toast('Ainda não há clube local para definir.');return}localClub.primary=true;saveOptions();refreshClub();toast(`${localClub.name} definido como clube principal local.`);return}toast('Uso: /club · /club invite [nome] · /club makeprimary');return}
  if(cmd==='zonerestrict'){const value=(arg||'').toLowerCase();if(!['public','private','officer'].includes(value)){toast('Uso: /zonerestrict [public/private/officer]');return}zoneRestriction=value;toast(`Permissão de construção simulada: ${value}. Não há construção online.`);return}
  if(cmd==='drawdistance'){const value=Number(arg);if(!Number.isFinite(value)||value<300||value>2000){toast('Distância válida: 300–2000. Ex.: /drawdistance 900');return}drawDistance=Math.round(value/100)*100;$('drawDistanceSetting').value=drawDistance;$('drawDistanceValue').value=drawDistance;saveOptions();toast(`Distância de renderização: ${drawDistance}.`);return}
  if(cmd==='fxenable'){if(!['0','1'].includes(arg)){toast('Uso: /fxenable [0 ou 1]');return}fxEnabled=arg==='1';$('fxSetting').checked=fxEnabled;saveOptions();if(!fxEnabled)camShake=0;toast(`Efeitos visuais ${fxEnabled?'ativados':'desativados'}.`);return}
  if(cmd==='help'){toast('/club · /club invite nome · /club makeprimary · /zonerestrict public|private|officer · /drawdistance 300–2000 · /fxenable 0|1');return}toast(`Comando desconhecido: /${cmd}. Use /help.`)}
$('commandForm').addEventListener('submit',e=>{e.preventDefault();runCommand($('commandInput').value);$('commandForm').classList.add('hidden');$('commandInput').blur()});
